SELECT percent_rank() OVER (ORDER BY avg_systolic_bp) AS percentile_rank FROM (SELECT AVG(value) AS avg_systolic_bp FROM chartevents JOIN icustays ON chartevents.subject_id = icustays.subject_id WHERE itemid = 85806002 AND valueuom = 'mm[Hg]' AND charttime BETWEEN intime AND (intime + interval '24 hours') AND (age(CURRENT_DATE, patient_dob) BETWEEN 87 AND 97) AND gender = 'F') AS subquery WHERE subquery.avg_systolic_bp >= 150;